WHERE a.deleted_at IS NULL
  AND a.protocol_account_id IS NOT NULL
  AND a.protocol_account_id <> ''
  AND s.account_state = #{normalAccountState}
  AND s.account_state <> #{exportedAccountState}

    AND a.account_type = #{criteria.accountType}


    AND a.protocol_id = #{criteria.protocolId}


    AND a.ws_phone LIKE CONCAT(#{criteria.phone}, '%')


    AND a.account_group_id IN

      #{groupId}



    AND a.account_group_id IN

      #{channelId}



    AND s.proxy_country IN

      #{iso2}



    AND (s.proxy_country IS NULL OR s.proxy_country NOT IN

      #{iso2}

    )


    AND s.contact_mutual_num >= #{criteria.friendCountMin}


    AND s.contact_mutual_num <= #{criteria.friendCountMax}


    AND a.created_at <= (UNIX_TIMESTAMP() * 1000 - #{criteria.registerDaysMin} * 86400000)


    AND a.created_at >= (UNIX_TIMESTAMP() * 1000 - #{criteria.registerDaysMax} * 86400000)
